/**
 * MARK: redactSecrets
 * @description Single content-redaction choke point for every log surface
 *   (embedded agent stream, runner ingest, committed task markdown, live
 *   socket payloads, report output tails). The only secret knowledge the
 *   engine previously had was the child-env name pattern
 *   (`SECRET_NAME_PATTERN` in `api/agent/harnesses/shared/harnessScaffold.js`,
 *   which drops secret-shaped env vars before spawning); anything a model,
 *   tool, or vendor echoed back into log TEXT was stored verbatim. This
 *   module redacts secret and PII shapes inside already-rendered text, so
 *   producers keep their grammar and clean inputs pass through byte-identical.
 *
 *   Pure module: zero dependencies, no harness imports — safe to import from
 *   the runner bundle, the log processor, and the UI.
 */

/***
 * MARK: REDACTED
 * @description Replacement markers. Each category keeps its own marker so a
 *   redacted log still tells the reader WHAT kind of value was hidden (a
 *   token vs an email vs a home directory) without revealing any of it.
 * @example REDACTED.TOKEN => '[REDACTED]'
 ***/
export const REDACTED = Object.freeze({
	SECRET: "[REDACTED]",
	TOKEN: "[REDACTED]",
	EMAIL: "[REDACTED EMAIL]",
	PHONE: "[REDACTED PHONE]",
	CARD: "[REDACTED CARD]",
	PATH: "[REDACTED]",
	KEY: "[REDACTED PRIVATE KEY]",
});

/***
 * MARK: redactSecretsText
 * @description Redacts secret and PII shapes inside one text value.
 *   Non-strings return "" (mirrors `stripAnsiText`); clean text returns
 *   unchanged (same reference semantics as String.replace with no match —
 *   callers can rely on byte-identical output for secret-free inputs).
 * @example redactSecretsText('hi') => 'hi'
 * @example redactSecretsText('Bearer abcdefgh1234') => 'Bearer [REDACTED]'
 * @param {string} text - Rendered log text that may carry secrets.
 * @returns {string} The text with secret/PII shapes replaced.
 ***/
export const redactSecretsText = (text) => {
	if (typeof text !== "string" || !text) return "";
	let out = text;
	// Private key blocks first: they span lines and contain base64 that
	// later patterns would only partially redact.
	out = out.replace(
		/-----BEGIN [A-Z0-9 ]*PRIVATE KEY-----[\s\S]*?-----END [A-Z0-9 ]*PRIVATE KEY-----/g,
		REDACTED.KEY,
	);
	// Bearer / Basic authorization headers.
	out = out.replace(/(bearer\s+)[A-Za-z0-9._~+/=-]{8,}/gi, `$1${REDACTED.SECRET}`);
	out = out.replace(/(basic\s+)[A-Za-z0-9._~+/=]{8,}/gi, `$1${REDACTED.SECRET}`);
	// Vendor token shapes.
	out = out.replace(/sk-(?:live|test|proj)-[A-Za-z0-9]{8,}/g, "sk-[REDACTED]");
	out = out.replace(/xox[baprs]-[A-Za-z0-9-]{8,}/g, "xox-[REDACTED]");
	out = out.replace(/\bgh[pousr]_[A-Za-z0-9]{8,}/g, "gh_[REDACTED]");
	out = out.replace(/AIza[0-9A-Za-z_-]{35}/g, "AIza[REDACTED]");
	out = out.replace(/AKIA[0-9A-Z]{16}/g, "AKIA[REDACTED]");
	// Connection strings and embedded-credential URLs: keep the scheme so
	// the reader still knows the backend kind, drop everything secret.
	out = out.replace(
		/(postgres(?:ql)?|mysql|mongodb(?:\+srv)?|redis(?:s)?|amqp(?:s)?):\/\/[^\s"'`]+/gi,
		`$1://${REDACTED.SECRET}`,
	);
	// Quadratic guard: this pattern opens with `\w+` (no literal anchor),
	// so a long run of word characters (base64 blobs, hashes, minified
	// tool output) costs O(n^2) — ~400ms for 20KB. Both `://` and `@` are
	// necessary for a match, so skip the scan when either is absent.
	if (out.includes("://") && out.includes("@")) {
		out = out.replace(/(\w+:\/\/[^/\s:]+:)[^@\s/]+@/g, `$1${REDACTED.SECRET}@`);
	}
	// AWS-style secret access keys inside JSON credential blobs.
	out = out.replace(
		/("(?:aws_secret|secret_access_key|session_token)"\s*:\s*")[^"]*(")/gi,
		`$1${REDACTED.SECRET}$2`,
	);
	// Labeled key/value pairs: api_key=..., "password": "...", CLIENT_SECRET: ...
	// The key list mirrors SECRET_NAME_PATTERN plus wire formats (apiKey,
	// client_secret, authToken). A real `:`/`=` separator is required — bare
	// prose ("secret reasoning step one") must never redact — and the value
	// needs at least 6 chars so short words after a colon survive.
	out = out.replace(
		/\b(api[_-]?key|auth[_-]?token|client[_-]?secret|credential(?:s)?|passwd|password|pwd|secret|token)\b(\s*["']?\s*[:=][=>]?\s*["']?)([A-Za-z0-9._~+/=:@-]{6,})/gi,
		`$1$2${REDACTED.SECRET}`,
	);
	// ENV-style assignments with secret-shaped names: FOOBAR_API_KEY="...".
	out = out.replace(
		/\b([A-Z][A-Z0-9_]*(?:SECRET|TOKEN|PASSWORD|PASSWD|PWD|CREDENTIAL|API[_-]?KEY|PRIVATE[_-]?KEY)[A-Z0-9_]*)\s*=\s*("[^"]*"|'[^']*'|[^\s,;}\]]+)/g,
		`$1=${REDACTED.SECRET}`,
	);
	// PII: emails, home directories (never /tmp or repo-relative paths),
	// phone shapes, and spaced/dashed 16-digit card runs.
	// Quadratic guard: the leading character class has no literal
	// anchor, so a long run of word characters costs O(n^2) (~450ms for
	// 20KB). `@` is necessary for a match, so skip the scan without it.
	if (out.includes("@")) {
		out = out.replace(
			/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g,
			REDACTED.EMAIL,
		);
	}
	out = out.replace(/\/(home|Users)\/[^\s/"'`:\n]+/g, `/$1/${REDACTED.PATH}`);
	out = out.replace(
		/\b(?:\+?1[-.\s]?)?\(?\d{3}\)?[-.\s]\d{3}[-.\s]\d{4}\b/g,
		REDACTED.PHONE,
	);
	out = out.replace(/\b\d{4}[- ]\d{4}[- ]\d{4}[- ]\d{4}\b/g, REDACTED.CARD);
	return out;
};

/***
 * MARK: SECRET_KEY_PATTERN
 * @description Secret-shaped object key names (mirrors `SECRET_NAME_PATTERN`
 *   in `api/agent/harnesses/shared/harnessScaffold.js`, extended to wire
 *   spellings like `apiKey`/`client_secret`). A string value under one of
 *   these keys is a secret by position even when the value itself carries no
 *   recognizable shape — the same rule the child-env seam already enforces.
 *   The `auth` alternative excludes `author`/`authors` (git authors, message
 *   authors) while still matching `authorization`/`authorize`: an author name
 *   is debugging context, never a credential.
 * @example SECRET_KEY_PATTERN.test("apiKey") => true
 * @example SECRET_KEY_PATTERN.test("model") => false
 * @example SECRET_KEY_PATTERN.test("author") => false
 * @example SECRET_KEY_PATTERN.test("authorization") => true
 ***/
export const SECRET_KEY_PATTERN =
	/secret|token|password|passwd|pwd|credential|api[_-]?key|private[_-]?key|access[_-]?key|client[_-]?secret|auth(?!or(?!iz))/i;

/***
 * MARK: isBinaryValue
 * @description Whether a value is raw binary bytes (an ArrayBuffer or a
 *   view over one: Buffer, Uint8Array, DataView). Log payloads are
 *   JSON-shaped, so binary never renders usefully — the deep redactor
 *   drops it behind a marker instead of decoding bytes that may hold secrets.
 * @example isBinaryValue(new Uint8Array([1])) => true
 * @example isBinaryValue("text") => false
 ***/
export const isBinaryValue = (value) =>
	typeof ArrayBuffer !== "undefined" &&
	(value instanceof ArrayBuffer ||
		(ArrayBuffer.isView?.(value) ?? false));

/***
 * MARK: redactDeepStrings
 * @description Deep-clones a JSON-ish value while redacting every string it
 *   contains. Used for structured payloads (tool args/results, permission
 *   targets, raw evidence) where a secret may sit in a nested field, not in
 *   rendered text. A string under a secret-shaped key (`SECRET_KEY_PATTERN`)
 *   is redacted by position even when the value looks innocent; numbers,
 *   booleans, null, and undefined pass through untouched (so usage token
 *   counts survive); circular values degrade to "[Unserializable]" instead of
 *   throwing. Dates keep their ISO text, Maps become plain objects, Sets
 *   become arrays, binary bytes become "[Binary]", bigints become their
 *   decimal text (JSON.stringify would throw on them downstream), and
 *   "__proto__" fields are dropped so the clone can never change its
 *   prototype. Total: hostile values (throwing getters, unlistable proxies)
 *   degrade to "[Unserializable]" at the closest level instead of throwing,
 *   so redacting a log line can never break the run it describes.
 * @example redactDeepStrings({ a: 'Bearer abcdefgh1234' }) => { a: 'Bearer [REDACTED]' }
 * @param {*} value - Any JSON-ish value.
 * @returns {*} A redacted deep clone.
 ***/
export const redactDeepStrings = (value) => {
	// Ancestor set only: a reference shared between siblings is cloned twice,
	// while a true cycle (an object reachable from itself) degrades safely.
	const ancestors = new Set();
	// Totality backstop: anything walkInner cannot handle (an unlistable
	// proxy, a throwing iterator) degrades to a marker at this level. The
	// inner finally blocks still run first, so the ancestor set stays exact.
	const walk = (node) => {
		try {
			return walkInner(node);
		} catch {
			return "[Unserializable]";
		}
	};
	const walkInner = (node) => {
		if (typeof node === "string") return redactSecretsText(node);
		if (typeof node === "bigint") return String(node);
		if (!node || typeof node !== "object") return node;
		// Dates carry no secrets and JSON-encode as ISO strings: keep the
		// readable timestamp instead of degrading to {} via Object.keys.
		if (node instanceof Date) {
			const time = node.getTime();
			return Number.isNaN(time) ? "[Invalid Date]" : node.toISOString();
		}
		if (node instanceof RegExp) return redactSecretsText(String(node));
		// Binary buffers never render usefully in a log row and may hold
		// secrets: drop them behind a marker instead of decoding bytes.
		if (isBinaryValue(node)) return "[Binary]";
		// Maps/Sets are not JSON log shapes: convert to plain data so the
		// values still redact instead of degrading to {}.
		if (node instanceof Map) {
			if (ancestors.has(node)) return "[Unserializable]";
			ancestors.add(node);
			try {
				const out = {};
				for (const [mapKey, mapValue] of node) {
					let key;
					try {
						key = typeof mapKey === "string" ? mapKey : String(mapKey);
					} catch {
						key = "[Unserializable]";
					}
					if (key === "__proto__") continue;
					if (typeof mapValue === "string" && SECRET_KEY_PATTERN.test(key)) {
						// eslint-disable-next-line security/detect-object-injection -- key is a Map key guarded against proto above
						out[key] = REDACTED.SECRET;
					} else {
						// eslint-disable-next-line security/detect-object-injection -- key is a Map key guarded against proto above
						out[key] = walk(mapValue);
					}
				}
				return out;
			} finally {
				ancestors.delete(node);
			}
		}
		if (node instanceof Set) {
			if (ancestors.has(node)) return "[Unserializable]";
			ancestors.add(node);
			try {
				return [...node].map(walk);
			} finally {
				ancestors.delete(node);
			}
		}
		if (ancestors.has(node)) return "[Unserializable]";
		ancestors.add(node);
		try {
			if (Array.isArray(node)) return node.map(walk);
			const out = {};
			for (const key of Object.keys(node)) {
				// Never copy __proto__: assigning it would change the clone's
				// prototype instead of storing a field (prototype pollution).
				if (key === "__proto__") continue;
				let child;
				try {
					// eslint-disable-next-line security/detect-object-injection -- key comes from Object.keys of the walked object
					child = node[key];
				} catch {
					// A throwing getter degrades to a marker on its own field
					// so sibling values still survive.
					// eslint-disable-next-line security/detect-object-injection -- key comes from Object.keys of the walked object
					out[key] = "[Unserializable]";
					continue;
				}
				if (typeof child === "string" && SECRET_KEY_PATTERN.test(key)) {
					// eslint-disable-next-line security/detect-object-injection -- key comes from Object.keys of the walked object
					out[key] = REDACTED.SECRET;
				} else {
					// eslint-disable-next-line security/detect-object-injection -- key comes from Object.keys of the walked object
					out[key] = walk(child);
				}
			}
			return out;
		} finally {
			ancestors.delete(node);
		}
	};
	return walk(value);
};

/**
 * MARK: logTagGrammar
 * @description The ONE tag grammar mapping a rendered log line to its
 *   structured entry kind and feed. Backend synthesis
 *   (`api/watch/processLogs.js`) and the frontend legacy parse
 *   (`frontend/src/components/tasks/logEntryModel.js`) both delegate here,
 *   so a tag can never classify one way in stored history and another way
 *   in the live view. The structured agent path never uses this — its
 *   records carry explicit kinds from the log processor; this grammar is
 *   only the fallback for tag-prefixed TEXT (command/git/CI output,
 *   runner text frames, legacy processLogs strings).
 *
 *   Pure module: zero dependencies — safe to import from the backend, the
 *   runner bundle, and the UI.
 */

/***
 * MARK: LOG_LINE_TAG_RULES
 * @description Tag prefix rules in match order (first match wins). No two
 *   rules overlap, so the order is documentation, not behavior — except
 *   that these run against the STDOUT-unwrapped line (see
 *   `classifyLogLineTag`).
 * @example LOG_LINE_TAG_RULES[0] => { pattern: /^\[(TOOL|RESULT)\]/, kind: 'tool', feed: 'tools' }
 ***/
const LOG_LINE_TAG_RULES = Object.freeze([
	{ pattern: /^\[(TOOL|RESULT)\]/, kind: "tool", feed: "tools" },
	// One rule covers `[RUNNER]` and `[runner <id>]`: after `[runner` the
	// next character is either `]` (caps form) or a space (inline form).
	{ pattern: /^\[runner[\] ]/i, kind: "runner", feed: "main" },
	{ pattern: /^\[THINKING\]/, kind: "thinking", feed: "thinking" },
	{ pattern: /^\[USAGE\]/, kind: "telemetry", feed: "telemetry" },
	{ pattern: /^\[RAW\]/, kind: "raw", feed: "raw" },
	{ pattern: /^\[PERM\]/, kind: "permission", feed: "main" },
	{ pattern: /^\[PLAN\]/, kind: "plan", feed: "main" },
	// Case-insensitive like every other error check in the UI: a lowercase
	// `[error]` line is still an error, not narrative.
	{ pattern: /^\[(ERROR|FAIL|STDERR)\]/i, kind: "error", feed: "main" },
	{
		pattern: /^\[(INFO|SYSTEM|GIT|CI\/CMD|CI|HUMAN|WARN)\]/,
		kind: "system",
		feed: "main",
	},
	{ pattern: /^\[AGENT\]/, kind: "assistant", feed: "main" },
]);

/***
 * MARK: classifyLogLineTag
 * @description Maps one rendered log chunk to its structured entry kind and
 *   feed using the shared tag grammar. Only the first line decides — except
 *   that a `[STDOUT]` stream wrapper unwraps to the second line, so the
 *   content tag classifies instead of the wrapper. (`[STDERR]` never
 *   unwraps: the error stream marker itself is the classification.)
 *   Untagged text is assistant narrative.
 * @example classifyLogLineTag('[TOOL] bash("ls")') => { kind: 'tool', feed: 'tools' }
 * @example classifyLogLineTag('[STDOUT]\n[AGENT] reasoning') => { kind: 'assistant', feed: 'main' }
 * @example classifyLogLineTag('plain narrative') => { kind: 'assistant', feed: 'main' }
 * @param {string} line - One rendered log chunk (may span lines).
 * @returns {{kind: string, feed: string}} The entry kind and feed.
 ***/
export function classifyLogLineTag(line) {
	const lines = String(line).split("\n");
	const firstLine = lines[0] || "";
	const checkLine =
		/^\[STDOUT\]/i.test(firstLine) && lines.length > 1 ? lines[1] : firstLine;
	const rule = LOG_LINE_TAG_RULES.find((candidate) =>
		candidate.pattern.test(checkLine),
	);
	if (rule) return { kind: rule.kind, feed: rule.feed };
	return { kind: "assistant", feed: "main" };
}

import { redactDeepStrings } from "../shared/redactSecrets.js";

/**
 * MARK: structuredEventSender
 * @description Batches normalized agent session events for the backend
 *   `POST /tasks/:id/log-events` endpoint (structured log transport). The
 *   sender redacts every event before it leaves the Runner (defense in depth
 *   for locally-read secrets), caps oversized payloads, and degrades to
 *   legacy text frames when the backend cannot take structured batches.
 *
 *   Failure policy (fail safe, never lose the log silently):
 *   - 404/405 (old backend without the route) and 400 (a batch the server
 *     refuses — retrying the identical batch would loop) fall back to text
 *     immediately: the failed batch AND everything still queued convert to
 *     text via `onTextFallback`, and later events flow through the daemon's
 *     `onLog` path instead (`isStructured()` goes false).
 *   - Anything else (network errors, timeouts, 5xx, lease conflicts) is
 *     transient: the failed batch is requeued at the FRONT with its SAME
 *     sequence number (the server dedupes a retry of a batch that actually
 *     landed; a fresh number would store the events twice) and a later
 *     flush retries. After MAX_STRUCTURED_SEND_FAILURES consecutive
 *     failures the sender gives up and falls back to text.
 *   - Unexpected fallbacks leave a one-line marker in the text stream so
 *     the UI reader knows the view is degraded; 404/405 (expected version
 *     skew during a mixed-version rollout) degrade silently to the
 *     long-standing coarse text view.
 *
 *   Pure batching over an injected client: no harness imports, no I/O of its
 *   own. The daemon owns the `onLog` gating via `isStructured()`.
 */

/***
 * MARK: MAX_EVENT_BYTES
 * @description Per-event JSON cap before transport. Oversized payloads (full
 *   file contents in a tool result) are truncated field-first, never dropped
 *   silently without the marker.
 * @example MAX_EVENT_BYTES => 65536
 ***/
export const MAX_EVENT_BYTES = 65536;

/***
 * MARK: MAX_BATCH_EVENTS
 * @description Most events in one transport batch. Mirrors the backend
 *   contract (`executionLedger.ingestLogEvents` rejects batches over 200):
 *   a flush with more queued sends several sequenced batches instead of
 *   one the server would refuse (which would flip the whole run to text).
 * @example MAX_BATCH_EVENTS => 200
 ***/
export const MAX_BATCH_EVENTS = 200;

/***
 * MARK: MAX_STRUCTURED_SEND_FAILURES
 * @description Consecutive transient send failures tolerated before the
 *   sender gives up on structured transport and falls back to text. One
 *   failure is a backend blip (a deploy restart mid-run must not cost the
 *   run its tool detail); this many in a row is an outage, and the text
 *   path preserves the narrative.
 * @example MAX_STRUCTURED_SEND_FAILURES => 5
 ***/
export const MAX_STRUCTURED_SEND_FAILURES = 5;

/***
 * MARK: sanitizeStructuredEvent
 * @description Makes one session event JSON-safe and transport-bounded:
 *   redacts secrets/PII (position- and shape-aware), drops functions and
 *   unserializable values via a JSON round-trip, and truncates oversized
 *   payload fields with a visible marker. Returns null when the event has no
 *   usable type or still exceeds the cap after truncation.
 * @example sanitizeStructuredEvent({ type: 'assistant_delta', delta: 'hi' }) => { type: 'assistant_delta', delta: 'hi' }
 * @param {Object} event - One normalized session event.
 * @param {number} [maxBytes] - Per-event JSON cap.
 * @returns {Object|null} The sanitized event, or null to skip it.
 ***/
export const sanitizeStructuredEvent = (event, maxBytes = MAX_EVENT_BYTES) => {
	if (!event || typeof event !== "object" || typeof event.type !== "string") {
		return null;
	}
	const cap = maxBytes > 0 ? maxBytes : MAX_EVENT_BYTES;
	let redacted;
	try {
		redacted = redactDeepStrings(event);
	} catch {
		return null;
	}
	const sizeOf = (value) => {
		try {
			return JSON.stringify(value)?.length ?? Infinity;
		} catch {
			return Infinity;
		}
	};
	if (sizeOf(redacted) <= cap) return redacted;
	// Truncate the large free-text payload fields first, keeping the event
	// envelope (type, toolName, meta) so the step stays visible.
	const truncated = { ...redacted };
	for (const field of ["result", "partialResult", "delta", "content", "text", "output"]) {
		if (typeof truncated[field] === "string" && truncated[field].length > 1000) {
			truncated[field] = `${truncated[field].slice(0, 1000)}…[truncated for transport]`;
		}
		if (sizeOf(truncated) <= cap) return truncated;
	}
	// Object-shaped payloads (e.g. result {content:[{text}]}) carry their
	// bulk in nested strings: truncate every long string in place (the
	// redacted clone is ours to mutate) before giving up on the event.
	const seen = new Set();
	const truncateDeep = (node) => {
		if (!node || typeof node !== "object" || seen.has(node)) return;
		// Note: Dates and RegExps cannot reach this walker (the redacted
		// clone converts them to strings), and they carry no enumerable
		// keys anyway, so there is deliberately no special case for them.
		seen.add(node);
		for (const key of Object.keys(node)) {
			// Never write __proto__: the redacted clone has none, and
			// assigning it would change the prototype instead of storing.
			if (key === "__proto__") continue;
			// eslint-disable-next-line security/detect-object-injection -- key comes from Object.keys of the walked payload
			const child = node[key];
			if (typeof child === "string" && child.length > 1000) {
				// eslint-disable-next-line security/detect-object-injection -- key comes from Object.keys of the walked payload
				node[key] = `${child.slice(0, 1000)}…[truncated for transport]`;
			} else {
				truncateDeep(child);
			}
		}
	};
	truncateDeep(truncated);
	if (sizeOf(truncated) <= cap) return truncated;
	return null;
};

/***
 * MARK: textForStructuredEvent
 * @description Legacy text derivation for one structured event — the same two
 *   shapes the pre-structured `onLog` path forwarded
 *   (`assistant_delta.delta`, `harness_log.text`). Returns null for
 *   tool/telemetry/permission/plan events, which have no legacy text form.
 * @example textForStructuredEvent({ type: 'assistant_delta', delta: 'hi' }) => 'hi'
 * @param {Object} event - One normalized session event.
 * @returns {string|null} The legacy text, or null when there is none.
 ***/
export const textForStructuredEvent = (event) => {
	if (!event || typeof event !== "object") return null;
	if (event.type === "assistant_delta" && typeof event.delta === "string") {
		return event.delta;
	}
	if (event.type === "harness_log" && typeof event.text === "string") {
		return event.text;
	}
	return null;
};

/***
 * MARK: describeSendError
 * @description One-line human reading of a transport failure for the runner
 *   log and the UI degradation marker: the HTTP status when the backend
 *   answered, then the message. Never renders "undefined" — a failure the
 *   sender cannot name is reported as an unknown error instead.
 * @example describeSendError(Object.assign(new Error('nope'), { statusCode: 500 })) => 'HTTP 500 nope'
 * @example describeSendError(undefined) => 'unknown error'
 * @param {*} err - Whatever the send threw.
 * @returns {string} The readable cause.
 ***/
export const describeSendError = (err) => {
	const status =
		err && typeof err === "object" && Number.isInteger(err.statusCode)
			? `HTTP ${err.statusCode} `
			: "";
	const message = err?.message || err || "unknown error";
	return `${status}${message}`;
};

/***
 * MARK: isVersionSkewFailure
 * @description Whether a send failure means the backend predates structured
 *   transport (unknown route): the expected state during a mixed-version
 *   rollout, so the sender degrades silently to the coarse text view.
 * @example isVersionSkewFailure(Object.assign(new Error('x'), { statusCode: 404 })) => true
 * @example isVersionSkewFailure(new Error('fetch failed')) => false
 * @param {*} err - Whatever the send threw.
 * @returns {boolean} True for 404/405 answers.
 ***/
export const isVersionSkewFailure = (err) => {
	const status = err?.statusCode;
	return status === 404 || status === 405;
};

/***
 * MARK: isPermanentSendFailure
 * @description Whether a send failure is unretryable: version skew (the
 *   route does not exist there) or a refused batch (retrying the identical
 *   bytes would fail the same way). Anything else is transient and worth
 *   retrying with the same sequence number.
 * @example isPermanentSendFailure(Object.assign(new Error('x'), { statusCode: 400 })) => true
 * @example isPermanentSendFailure(Object.assign(new Error('x'), { statusCode: 500 })) => false
 * @param {*} err - Whatever the send threw.
 * @returns {boolean} True when retrying cannot help.
 ***/
export const isPermanentSendFailure = (err) => {
	if (isVersionSkewFailure(err)) return true;
	return err?.statusCode === 400;
};

/***
 * MARK: createStructuredEventSender
 * @description Buffers sanitized session events and ships them as sequenced
 *   batches of at most `batchSize` events (never more than
 *   MAX_BATCH_EVENTS, the server's per-batch cap). Flushes on `batchSize`
 *   queued, on `flushMs` of quiet, on explicit `flush()`/`close()`, and
 *   immediately on run-closing events (`run_finished`, `run_error`) so the
 *   tail never waits for the timer. `flushMs <= 0` disables the quiet timer
 *   (explicit flush/close only).
 *
 *   Delivery contract: `flush()` drains everything queued, INCLUDING events
 *   that arrived while a batch was in flight — except that a TRANSIENT
 *   send failure ends the pass with the failed batch requeued at the front
 *   (same sequence number; a later flush retries it). `close()` keeps
 *   flushing until the queue is empty, then — only if the backend stayed
 *   unreachable — falls back, so the caller can rely on the tail landing
 *   before it reports the stage complete. Permanent failures (404/405/400)
 *   fall back immediately instead of retrying.
 * @example const sender = createStructuredEventSender({ client, taskId: 't', projectId: 'p', executionId: 'e', epoch: 1, onTextFallback: () => {} })
 * @param {Object} opts - Options.
 * @param {Object} opts.client - Runner backend client with `logEvents`.
 * @param {string} opts.taskId - Task id.
 * @param {string} opts.projectId - Project id.
 * @param {string} opts.executionId - Lease execution id.
 * @param {number} opts.epoch - Lease epoch.
 * @param {Function} [opts.onTextFallback] - Called with legacy text per convertible event after the fallback flip (plus one degradation marker for unexpected failures).
 * @param {Object} [opts.logger] - Logger for send warnings.
 * @param {number} [opts.batchSize=25] - Events queued per batch (clamped to 1–200).
 * @param {number} [opts.flushMs=500] - Quiet-ms before a partial batch ships (<=0 disables).
 * @returns {Object} Sender with `queueEvent`, `flush`, `close`, `isStructured`.
 ***/
export const createStructuredEventSender = ({
	client,
	taskId,
	projectId,
	executionId,
	epoch,
	onTextFallback = () => {},
	logger = null,
	batchSize = 25,
	flushMs = 500,
}) => {
	let seq = 0;
	let pending = [];
	let structured = true;
	let timer = null;
	let inFlight = null;
	let consecutiveSendFailures = 0;
	// One batch never exceeds the server's per-batch cap, however large
	// the caller sizes its batches: an oversized batch would be refused
	// outright (400) and flip the whole run to text.
	const eventsPerBatch = Math.min(
		Math.max(1, batchSize),
		MAX_BATCH_EVENTS,
	);

	const warn = (message) => {
		try {
			if (logger && typeof logger.warn === "function") logger.warn(message);
		} catch {
			// Logging must never break the run.
		}
	};

	const clearTimer = () => {
		if (timer) {
			clearTimeout(timer);
			timer = null;
		}
	};

	const armTimer = () => {
		if (timer || flushMs <= 0) return;
		timer = setTimeout(() => {
			timer = null;
			flush().catch(() => {});
		}, flushMs);
		if (typeof timer.unref === "function") timer.unref();
	};

	const sendBatch = async (batch, batchSeq) => {
		await client.logEvents({
			taskId,
			projectId,
			executionId,
			epoch,
			seq: batchSeq,
			events: batch,
		});
	};

	const fallBack = (failedBatch, err) => {
		structured = false;
		clearTimer();
		// Convert everything not yet sent, not just the failed batch: events
		// queued while that batch was in flight were never transported
		// structured and must not vanish during the fallback transition.
		const unsent = [...failedBatch, ...pending];
		pending = [];
		const cause = describeSendError(err);
		warn(`Structured log transport failed (${cause}); falling back to text frames.`);
		// Unexpected outages leave a visible marker so the UI reader knows
		// the view is degraded; version skew (old backend) degrades
		// silently to the long-standing coarse text view.
		if (!isVersionSkewFailure(err)) {
			try {
				onTextFallback(
					`[runner] structured log transport failed (${cause}); showing text only`,
				);
			} catch {
				// A throwing fallback must never break the run.
			}
		}
		for (const event of unsent) {
			const text = textForStructuredEvent(event);
			if (text) {
				try {
					onTextFallback(text);
				} catch {
					// A throwing fallback must never break the run.
				}
			}
		}
	};

	const flush = async () => {
		// Drain loop, not a single pass: events queued while a batch is in
		// flight must ship too. Taking a batch (`pending` splice) is
		// synchronous, so concurrent flushes can never send the same events
		// twice. A flush waits for a batch another caller started even when
		// the queue looks empty: that batch may fail and requeue, and the
		// waiter must see the requeued events, not resolve early. A
		// transient failure ends the pass with the batch requeued (same
		// seq) instead of looping hot against a dead backend — the quiet
		// timer or the next events retry it.
		for (;;) {
			if (!structured) return;
			if (inFlight) {
				await inFlight;
				continue;
			}
			if (pending.length === 0) return;
			const batch = pending.splice(0, eventsPerBatch);
			clearTimer();
			const batchSeq = seq;
			seq += 1;
			let outcome = null;
			inFlight = sendBatch(batch, batchSeq).then(
				() => {
					outcome = { ok: true };
				},
				(err) => {
					outcome = { ok: false, err };
				},
			);
			try {
				await inFlight;
			} finally {
				inFlight = null;
			}
			if (outcome.ok) {
				consecutiveSendFailures = 0;
				continue;
			}
			consecutiveSendFailures += 1;
			if (
				isPermanentSendFailure(outcome.err) ||
				consecutiveSendFailures >= MAX_STRUCTURED_SEND_FAILURES
			) {
				fallBack(batch, outcome.err);
				return;
			}
			// Transient: retry later with the SAME sequence number. The
			// server dedupes a retry of a batch that actually landed (the
			// response may have been lost, not the batch); a fresh number
			// would store the events twice.
			seq = batchSeq;
			pending = [...batch, ...pending];
			warn(
				`Structured log transport failed (${describeSendError(outcome.err)}); will retry ${pending.length} queued event(s).`,
			);
			armTimer();
			return;
		}
	};

	const queueEvent = (event) => {
		if (!structured) return;
		const closesRun = event?.type === "run_finished" || event?.type === "run_error";
		const sanitized = sanitizeStructuredEvent(event);
		if (!sanitized) {
			// A dropped closing event must still flush what is already
			// queued: the tail must never wait for the timer just because
			// the final envelope was oversized or unusable.
			if (closesRun) flush().catch(() => {});
			return;
		}
		pending.push(sanitized);
		if (closesRun || pending.length >= Math.max(1, batchSize)) {
			flush().catch(() => {});
			return;
		}
		armTimer();
	};

	const close = async () => {
		clearTimer();
		// Close is the last trigger, so it retries the drain itself: a
		// transient failure leaves events queued for "a later flush" that
		// would never come. Each failing pass counts toward the bound, so
		// a dead backend still terminates — by falling back, which attempts
		// the tail as text rather than dropping it silently.
		for (;;) {
			await flush();
			if (!structured || pending.length === 0) return;
		}
	};

	const isStructured = () => structured;

	return { queueEvent, flush, close, isStructured };
};

// Domain: Watching the Work — task progress entries and their feeds.
import { config } from "../config.js";
import { redactDeepStrings, redactSecretsText } from "../../shared/redactSecrets.js";
import { classifyLogLineTag } from "../../shared/logTagGrammar.js";
/***
 * MARK: _logEntryKindFromText
 * @description Maps a rendered log chunk to its structured entry kind and
 *   feed. Delegates to the shared tag grammar (`classifyLogLineTag`) — the
 *   single source this file and the frontend legacy parse both read, so a
 *   tag can never classify one way in stored history and another way live.
 *   Untagged text is assistant narrative.
 * @example _logEntryKindFromText('[TOOL] bash(…)') => { kind: 'tool', feed: 'tools' }
 * @param {string} text
 * @returns {{kind: string, feed: string}}
 ***/
function _logEntryKindFromText(text) {
	return classifyLogLineTag(text);
}

/** Monotonic counter for synthesized log entry ids (never Date.now() so
 *  same-millisecond entries cannot collide). */
let _logEntryIdCounter = 0;

/***
 * MARK: _synthesizedLogEntry
 * @description Wraps a rendered log chunk as a structured log entry so the
 *   UI has one uniform shape for every log source (agent streamer entries
 *   and system/GIT/CI lines alike).
 * @example _synthesizedLogEntry('[GIT] Switched to main') => { kind: 'system', text: '…', … }
 * @param {string} chunk
 * @param {Object} [meta] - Extra entry metadata (e.g. `{ runnerId }`). A
 *   caller `source` is ignored: synthesis owns that stamp (see below).
 * @returns {Object} A structured log entry.
 ***/
function _synthesizedLogEntry(chunk, meta = {}) {
	_logEntryIdCounter += 1;
	const { kind, feed } = _logEntryKindFromText(chunk);
	// Only a plain bag spreads into meta: exotic inputs (strings, Dates,
	// arrays) degrade to {} instead of scattering characters into the entry.
	const cleanedMeta = redactDeepStrings(meta || {});
	const metaBag =
		cleanedMeta && typeof cleanedMeta === "object" && !Array.isArray(cleanedMeta)
			? cleanedMeta
			: {};
	return {
		id: `log-${_logEntryIdCounter}`,
		ts: new Date().toISOString(),
		feed,
		feeds: [feed],
		kind,
		turn: null,
		// Redacted at synthesis so command output, git lines, and runner
		// text frames can never store secrets or PII. Clean text passes
		// through byte-identical.
		text: redactSecretsText(String(chunk)),
		// The source stamp is forced AFTER the spread: the live view
		// trusts `source` to tell the text lane from the structured lane
		// when hiding already-stored frames, so a caller must never be
		// able to stamp a text frame as structured (which could hide a
		// structured frame that was never stored). No caller sets it.
		meta: { ...metaBag, source: "process-log" },
	};
}

/***
 * MARK: _capLogEntries
 * @description Keeps at most `config.logEntriesMaxCount` entries on a task,
 *   dropping the oldest and recording the eviction under a single updating
 *   marker entry (mirrors the streamer's eviction behaviour).
 * @example _capLogEntries(task)
 * @param {Object} task
 * @returns {void}
 ***/
function _capLogEntries(task) {
	const max = config.logEntriesMaxCount;
	if (!Array.isArray(task.logEntries) || task.logEntries.length <= max) return;
	const existingMarker = task.logEntries[0];
	const hasMarker = existingMarker?.meta?.evictedCount !== undefined;
	// Reserve one slot for the marker so the cap holds after it is unshifted.
	const keepTarget = hasMarker ? max : max - 1;
	const overflow = task.logEntries.length - keepTarget;
	if (overflow <= 0) return;
	task.logEntries.splice(hasMarker ? 1 : 0, overflow);
	const markerText = `[INFO] (${overflow} earlier log entries evicted)`;
	if (hasMarker) {
		const previousCount = existingMarker.meta.evictedCount + overflow;
		existingMarker.text = `[INFO] (${previousCount} earlier log entries evicted)`;
		existingMarker.meta = { evictedCount: previousCount };
	} else {
		_logEntryIdCounter += 1;
		task.logEntries.unshift({
			id: `log-${_logEntryIdCounter}`,
			ts: new Date().toISOString(),
			feed: "main",
			feeds: ["main"],
			kind: "system",
			turn: null,
			text: markerText,
			meta: { evictedCount: overflow },
		});
	}
}

/***
 * MARK: parseLegacyProcessLogText
 * @description Parses legacy rendered process-log text (line-based tag
 *   grammar) into structured entries (blank lines dropped, consecutive
 *   duplicates de-duped) so tasks predating the structured-entries era still
 *   serve feeds. Shared by the markdown legacy-section synthesis
 *   (`parseTaskMarkdown`) and the in-memory feed fallback below — it is a
 *   read-only migration path, never a second storage format.
 * @example parseLegacyProcessLogText('[INFO] a\n[INFO] a') => [entry('[INFO] a')]
 * @param {string} text
 * @returns {Array<Object>} Structured log entries.
 ***/
export function parseLegacyProcessLogText(text) {
	const source = typeof text === "string" ? text : "";
	if (!source.trim()) return [];
	const parsed = [];
	for (const line of source.split("\n")) {
		if (!line.trim()) continue;
		if (parsed.length > 0 && parsed[parsed.length - 1].text === line) continue;
		parsed.push(_synthesizedLogEntry(line));
	}
	return parsed;
}

/***
 * MARK: renderLogEntriesText
 * @description The ONE shared renderer from structured log entries to legacy
 *   tag-grammar text — every text view is derived here at read time, never
 *   stored. With a `feed` option only that feed's entries render; without
 *   one, the combined main+tools narrative renders (thinking entries stay
 *   out, mirroring the streamer's combined view).
 * @example renderLogEntriesText(entries) => "[AGENT] reasoning…\n[TOOL] bash(…)"
 * @example renderLogEntriesText(entries, { feed: 'tools' }) => "[TOOL] bash(…)"
 * @param {Array<Object>} entries
 * @param {{ feed?: string }} [opts]
 * @returns {string}
 ***/
export function renderLogEntriesText(entries, { feed } = {}) {
	const selected = (Array.isArray(entries) ? entries : []).filter((entry) => {
		if (!entry) return false;
		const placed = Array.isArray(entry.feeds) ? entry.feeds : [entry.feed];
		if (feed) return placed.includes(feed);
		return placed.includes("main") || placed.includes("tools");
	});
	return selected.map((entry) => entry.text).join("\n");
}

/***
 * MARK: _logEntriesForFeed
 * @description Collects a task's entries placed on one feed (main/thinking/
 *   tools), bounded to `config.logEntriesMaxCount`. Structured entries are
 *   the single storage path; the legacy-text fallback only exists for tasks
 *   still carrying a pre-migration `processLogs` string (read-only).
 * @example _logEntriesForFeed(task, 'thinking') => [thinkingEntry, …]
 * @param {Object} task
 * @param {string} feed
 * @returns {Array<Object>} The feed's entries, oldest first.
 ***/
export function _logEntriesForFeed(task, feed) {
	const structured = Array.isArray(task?.logEntries)
		? task.logEntries.filter(Boolean)
		: [];
	const all =
		structured.length > 0
			? structured
			: parseLegacyProcessLogText(task?.processLogs);
	const matching = all.filter((entry) =>
		(Array.isArray(entry.feeds) ? entry.feeds : [entry.feed]).includes(feed),
	);
	const capped = { logEntries: matching };
	_capLogEntries(capped);
	return capped.logEntries;
}

/***
 * MARK: _appendLogEntries
 * @description Appends structured log entries to task.logEntries, capping the
 *   array to `config.logEntriesMaxCount`.
 * @example _appendLogEntries(task, streamer.snapshot().entries)
 * @param {Object} task
 * @param {Array<Object>} newEntries
 * @returns {void}
 ***/
export function _appendLogEntries(task, newEntries) {
	if (!task || !Array.isArray(newEntries)) return;
	if (!Array.isArray(task.logEntries)) task.logEntries = [];
	for (const entry of newEntries) {
		if (entry) task.logEntries.push(entry);
	}
	_capLogEntries(task);
}

/***
 * MARK: _replaceLogEntries
 * @description Replaces the log entries accumulated for one stage run (the
 *   synthesized tail of the array) with the agent streamer's structured
 *   entries, upgrading turn-grouped text blocks into the task's log.
 * @example _replaceLogEntries(task, startIndex, result.logEntries)
 * @param {Object} task
 * @param {number} startIndex - Index where the stage's entries begin.
 * @param {Array<Object>} entries - The structured entries for the stage.
 * @returns {void}
 ***/
export function _replaceLogEntries(task, startIndex, entries) {
	if (!task || !Array.isArray(entries)) return;
	if (!Array.isArray(task.logEntries)) task.logEntries = [];
	const safeStart = Math.max(0, Math.min(startIndex, task.logEntries.length));
	task.logEntries.splice(safeStart);
	_appendLogEntries(task, entries);
}

/***
 * MARK: _appendProcessLog
 * @description Appends a rendered log chunk to the task's structured
 *   `logEntries` as one synthesized entry — the single log storage path
 *   (agent streamer entries replace the synthesized ones when the stage
 *   result arrives). Growth is bounded by `config.logEntriesMaxCount` with
 *   an eviction marker; the historical rendered-text copy
 *   (`task.processLogs`) is gone and every text view is derived from entries
 *   at read time via `renderLogEntriesText`.
 * @example _appendProcessLog(task, '[GIT] Switched to main')
 * @param {Object} task
 * @param {string} chunk
 * @param {Object} [meta] - Extra entry metadata (e.g. `{ runnerId }`).
 * @returns {void}
 ***/
export function _appendProcessLog(task, chunk, meta = {}) {
	if (!task || !chunk) return;
	const trimmed = String(chunk).trim();
	if (!trimmed) return;
	_appendLogEntries(task, [_synthesizedLogEntry(trimmed, meta)]);
}

/**
 * MARK: logProcessor
 * @description THE single place that turns normalized agent events into
 *   canonical log records (`logRecord.js`). The agent log streamer
 *   (`agentLogStreamer.js`) is a thin stateful shell around this processor:
 *   it owns feed plumbing (consumeFeed/snapshot/render) while every
 *   event→record decision lives here, so harnesses and the UI can migrate
 *   independently once this seam and its contract test exist.
 *
 *   Responsibilities:
 *   - block state (text/thinking/tool) and `blockId` assignment;
 *   - telemetry/permission/plan/raw lanes for the unified vocabulary
 *     (`usage_updated`, `session_meta`, `permission_requested/resolved`,
 *     `plan_updated`, `reasoning_delta`, `harness_log`);
 *   - usage telemetry derived from `usage` payloads riding on
 *     `assistant_delta`/`run_finished` (pi message usage/stopReason, agy
 *     result usage) as well as explicit `usage_updated` events;
 *   - unknown-event capture into the bounded raw lane
 *     (`evidence.reason = "unmapped"`) instead of silent drops;
 *   - caps/eviction per lane and total (`logEntriesMaxCount`);
 *   - ANSI strip for `text` (preserved verbatim in `evidence.sourceEvent`).
 *
 *   Backwards compatibility: for the original 8 events the produced entries
 *   keep their exact kind/feed/text/meta — the new canonical fields (`seq`,
 *   `blockId`, `fidelity`, …) are purely additive.
 */

import {
	boundRawSource,
	FIDELITY_SYNTHESIZED,
	makeLogRecord,
	RECORD_LIMITS,
	stripAnsiText,
} from "./logRecord.js";
import {
	redactDeepStrings,
	redactSecretsText,
} from "../../../shared/redactSecrets.js";
import {
	summarizePermission,
	summarizePlan,
	summarizeRaw,
	summarizeToolResult,
	summarizeToolStart,
	summarizeUsage,
} from "../../../shared/toolLogFormat.js";

/***
 * MARK: DEFAULT_PROCESSOR_OPTIONS
 * @description Default options for `createLogProcessor`. Mirrors the
 *   streamer defaults (`maxEntryBytes` 0 = uncapped narrative text; task-log
 *   growth bounded by the structured-entry cap) plus the unified lane
 *   budgets (`telemetryMaxCount`, `rawMaxCount`, `rawMaxBytes`).
 ***/
export const DEFAULT_PROCESSOR_OPTIONS = Object.freeze({
	hideThinking: true,
	toolArgsMaxLength: 400,
	resultMaxLength: 600,
	maxEntryBytes: 0,
	maxEntries: 500,
	telemetryMaxCount: RECORD_LIMITS.telemetryMaxCount,
	rawMaxCount: RECORD_LIMITS.rawMaxCount,
	rawMaxBytes: RECORD_LIMITS.rawMaxBytes,
	harnessId: undefined,
	model: undefined,
	runId: undefined,
});

/***
 * MARK: excerptText
 * @description Bounds a text block to `maxLength` characters, appending an
 *   ellipsis when the text was cut. Storage caps only — display lines
 *   summarize through the shared toolLogFormat grammar instead.
 ***/
function excerptText(text, maxLength) {
	if (!maxLength || maxLength <= 0 || text.length <= maxLength) return text;
	return `${text.slice(0, maxLength)}…`;
}

/***
 * MARK: extractToolResultText
 * @description Flattens a tool_finished result payload into plain text, using
 *   the same shapes the engine has always read: plain string, `{content}`
 *   string, `{content: [{text}]}` array, or a JSON fallback. Redacted on the
 *   way out: the flattened text is appended to the already-stored [TOOL]
 *   entry (`meta.output`) AFTER its record passed the creation redactor, so
 *   an unredacted extract would leak secrets into the store.
 ***/
function extractToolResultText(event) {
	const flatten = () => {
		if (typeof event.result === "string") return event.result;
		if (typeof event.result?.content === "string") return event.result.content;
		if (Array.isArray(event.result?.content)) {
			return event.result.content
				.map((c) => (typeof c === "string" ? c : c?.text || ""))
				.join("");
		}
		if (event.result) {
			try {
				return JSON.stringify(event.result);
			} catch {
				return String(event.result);
			}
		}
		return "";
	};
	return redactSecretsText(flatten());
}

/***
 * MARK: readToolPartial
 * @description Reads the streamed partial output of a tool_updated event,
 *   redacted: partials accumulate on the stored [TOOL] entry after its
 *   record passed the creation redactor.
 ***/
function readToolPartial(event) {
	if (typeof event.partialResult === "string")
		return redactSecretsText(event.partialResult);
	if (typeof event.delta === "string") return redactSecretsText(event.delta);
	return "";
}

/***
 * MARK: createLogProcessor
 * @description Creates the unified event→record processor for one agent
 *   stage run. Pure: no harness imports, no I/O — only the normalized
 *   agent-event vocabulary in, canonical records out.
 * @param {Object} [options] - See DEFAULT_PROCESSOR_OPTIONS.
 * @returns {Object} Processor with handleEvent/system/entries/snapshot helpers.
 ***/
export function createLogProcessor(options = {}) {
	const merged = { ...DEFAULT_PROCESSOR_OPTIONS, ...options };
	const hideThinking = merged.hideThinking !== false;
	const toolArgsMaxLength =
		merged.toolArgsMaxLength ?? DEFAULT_PROCESSOR_OPTIONS.toolArgsMaxLength;
	const resultMaxLength =
		merged.resultMaxLength ?? DEFAULT_PROCESSOR_OPTIONS.resultMaxLength;
	const maxEntryBytes = merged.maxEntryBytes || 0;
	const maxEntries =
		merged.maxEntries > 0 ? merged.maxEntries : DEFAULT_PROCESSOR_OPTIONS.maxEntries;
	const telemetryMaxCount =
		merged.telemetryMaxCount > 0
			? merged.telemetryMaxCount
			: DEFAULT_PROCESSOR_OPTIONS.telemetryMaxCount;
	const rawMaxCount =
		merged.rawMaxCount > 0 ? merged.rawMaxCount : DEFAULT_PROCESSOR_OPTIONS.rawMaxCount;
	const rawMaxBytes =
		merged.rawMaxBytes > 0 ? merged.rawMaxBytes : DEFAULT_PROCESSOR_OPTIONS.rawMaxBytes;
	const contextFields = {};
	if (typeof merged.harnessId === "string" && merged.harnessId) {
		contextFields.harnessId = merged.harnessId;
	}
	if (merged.model !== undefined && merged.model !== null) {
		contextFields.model = merged.model;
	}
	if (typeof merged.runId === "string" && merged.runId) {
		contextFields.runId = merged.runId;
	}

	/** Monotonic entry ids: never Date.now() so same-millisecond events cannot collide. */
	let nextEntryId = 1;
	/** Monotonic record sequence numbers for the canonical record. */
	let nextSeq = 1;
	/** Semantic block counter: one blockId per text/thinking/tool block. */
	let nextBlock = 1;
	/** 1-based turn counter (run_started … run_finished). */
	let turnIndex = 0;
	/** All retained entries in creation order. */
	const entries = [];
	/** Open assistant text block for the streaming message. */
	let textBuffer = "";
	/** Open thinking block for the streaming message. */
	let thinkingBuffer = "";
	/** Role of the message currently streaming (assistant …). */
	let messageRole = null;
	/** The tool entry currently accumulating output (tool_started … tool_finished). */
	let openToolEntry = null;
	/** Wall-clock start per open tool entry (WeakMap so parallel calls keep
	 *  their own start; never stored on the record itself). */
	const toolStartMs = new WeakMap();
	/** Steps faster than this render no measured timing suffix: same-tick
	 *  unit pairs stay byte-identical while real tool calls (≥100ms) show
	 *  how long each step took. Explicit event timings always render. */
	const MEASURED_TIMING_FLOOR_MS = 100;

	const firstFiniteMs = (...values) => {
		for (const value of values) {
			if (typeof value === "number" && Number.isFinite(value) && value >= 0) {
				return value;
			}
		}
		return null;
	};

	const explicitDurationMs = (event = {}) =>
		firstFiniteMs(
			event.durationMs,
			event.duration_ms,
			typeof event.duration_seconds === "number" ? event.duration_seconds * 1000 : null,
			typeof event.durationSeconds === "number" ? event.durationSeconds * 1000 : null,
		);

	const formatDurationMs = (ms) =>
		ms >= 1000 ? `${(ms / 1000).toFixed(1)}s` : `${Math.round(ms)}ms`;
	/** Marker entry tracking evicted entries, so repeated eviction updates one line. */
	let evictionMarker = null;
	let evictedCount = 0;
	/** Marker entry tracking raw-lane evictions (stays on the raw feed). */
	let rawEvictionMarker = null;
	let rawEvictedCount = 0;
	/** Telemetry records retained (reserved budget inside maxEntries). */
	let telemetryCount = 0;
	/** Last emitted usage payload JSON — suppresses double telemetry when the
	 *  same usage object arrives both as usage_updated and on run_finished. */
	let lastUsageJson = null;

	const capText = (text) =>
		maxEntryBytes > 0 ? excerptText(text, maxEntryBytes) : text;

	const appendRecord = (partial) => {
		const record = makeLogRecord({
			...contextFields,
			turn: turnIndex || 1,
			...partial,
			id: nextEntryId++,
			seq: nextSeq++,
			ts: new Date().toISOString(),
		});
		// ANSI escapes never reach stored text (they would leak into HTML
		// rendering); the verbatim wire bytes stay available in evidence.
		// Secrets/PII are redacted BEFORE the length cap so a truncated
		// secret fragment can never survive beside a cut marker. Clean text
		// passes through byte-identical.
		if (typeof record.text === "string" && record.text) {
			record.text = capText(redactSecretsText(stripAnsiText(record.text)));
		}
		// Structured payloads redact by position (secret-shaped keys) and by
		// shape (tokens, emails, paths inside free text). Numbers/booleans
		// pass through untouched, so usage counts and exit codes survive.
		if (record.meta && typeof record.meta === "object") {
			record.meta = redactDeepStrings(record.meta);
		}
		if (record.tool && typeof record.tool === "object") {
			record.tool = redactDeepStrings(record.tool);
		}
		if (record.usage && typeof record.usage === "object") {
			record.usage = redactDeepStrings(record.usage);
		}
		if (record.evidence && typeof record.evidence === "object") {
			record.evidence = redactDeepStrings(record.evidence);
		}
		// No `detail` branch: records never carry one — `makeLogRecord`
		// only copies its declared fields, and the UI builds expandable
		// detail at read time from tool/usage/evidence (see
		// `renderEntryDetail`). Every redacted field above is one the
		// record shape actually has.
		entries.push(record);
		evictOverflow();
		return record;
	};

	const appendEntry = ({ kind, feeds: entryFeeds, text, meta, ...rest }) => {
		return appendRecord({
			kind,
			feeds: entryFeeds,
			feed: entryFeeds[0],
			text,
			meta: meta || {},
			...rest,
		});
	};

	function evictOverflow() {
		// Reserve one slot for the eviction marker so the cap holds after it is
		// unshifted (and don't double-reserve once the marker exists). The
		// marker itself is exempt from eviction and always stays at the front.
		const hasMarker = Boolean(evictionMarker && entries.includes(evictionMarker));
		const overflow = entries.length + (hasMarker ? 0 : 1) - maxEntries;
		if (overflow <= 0) return;
		evictedCount += overflow;
		entries.splice(hasMarker ? 1 : 0, overflow);
		if (evictionMarker && !entries.includes(evictionMarker)) {
			evictionMarker = null;
			rawEvictionMarker = null;
		}
		if (rawEvictionMarker && !entries.includes(rawEvictionMarker)) {
			rawEvictionMarker = null;
		}
		const markerText = `[INFO] (${evictedCount} earlier log entries evicted)`;
		if (!evictionMarker) {
			evictionMarker = makeLogRecord({
				...contextFields,
				id: nextEntryId++,
				seq: nextSeq++,
				ts: new Date().toISOString(),
				feed: "main",
				feeds: ["main"],
				kind: "system",
				turn: turnIndex || 1,
				text: markerText,
				meta: { evictedCount },
				fidelity: FIDELITY_SYNTHESIZED,
			});
			entries.unshift(evictionMarker);
		} else {
			evictionMarker.text = markerText;
			evictionMarker.meta = { evictedCount };
		}
		reconcileLaneCounters();
	}

	function reconcileLaneCounters() {
		telemetryCount = entries.filter((e) => e.kind === "telemetry").length;
	}

	function flushText() {
		if (!textBuffer.trim()) {
			textBuffer = "";
			return null;
		}
		const entry = appendEntry({
			kind: "assistant",
			feeds: ["main"],
			text: textBuffer,
			meta: { messageRole: messageRole || "assistant" },
			blockId: `b${nextBlock++}`,
		});
		textBuffer = "";
		return entry;
	}

	function flushThinking() {
		if (!thinkingBuffer.trim()) {
			thinkingBuffer = "";
			return null;
		}
		const block = thinkingBuffer;
		thinkingBuffer = "";
		const charCount = block.length;
		const blockId = `b${nextBlock++}`;
		if (hideThinking) {
			const fullEntry = appendEntry({
				kind: "thinking",
				feeds: ["thinking"],
				text: block,
				meta: { messageRole: messageRole || "assistant", charCount },
				blockId,
			});
			return appendEntry({
				kind: "thinking",
				feeds: ["main"],
				text: `[THINKING] (${charCount} chars)`,
				meta: {
					messageRole: messageRole || "assistant",
					charCount,
					collapsed: true,
					fullTextId: fullEntry.id,
				},
				blockId,
			});
		}
		return appendEntry({
			kind: "thinking",
			feeds: ["main", "thinking"],
			text: block,
			meta: { messageRole: messageRole || "assistant", charCount },
			blockId,
		});
	}

	function flushOpenBlocks() {
		const flushed = [];
		// Thinking flushes before text: models emit thinking first, so markers
		// land above the narrative they precede.
		const thinkingEntries = flushThinking();
		if (Array.isArray(thinkingEntries)) {
			flushed.push(...thinkingEntries);
		} else if (thinkingEntries) {
			flushed.push(thinkingEntries);
		}
		const textEntry = flushText();
		if (textEntry) flushed.push(textEntry);
		return flushed;
	}

	function formatRunOpenLine(event) {
		const facts = event.runFacts;
		if (!facts || facts.harness !== "antigravity") return null;
		const parts = [`model=${facts.model || "agy default"}`];
		if (facts.effort) parts.push(`effort=${facts.effort}`);
		parts.push(`sandbox=${facts.sandbox ? "on" : "off"}`);
		parts.push(`approvals=${facts.skipPermissions ? "auto" : "prompt"}`);
		if (event.permissionMode)
			parts.push(`permission_mode=${event.permissionMode}`);
		if (event.conversationId)
			parts.push(`conversation=${String(event.conversationId).slice(0, 8)}`);
		return `[AGY] run open: ${parts.join(" ")}`;
	}

	function formatRunDoneLine(event) {
		const facts = event.runFacts;
		if (!facts || facts.harness !== "antigravity") return null;
		const usage = event.usage || {};
		/* eslint-disable security/detect-object-injection -- keys are compile-time constants */
		const total =
			typeof usage.total_tokens === "number"
				? usage.total_tokens
				: ["input_tokens", "output_tokens", "thinking_tokens"].reduce(
						(sum, key) => sum + (typeof usage[key] === "number" ? usage[key] : 0),
						0,
					);
		/* eslint-enable security/detect-object-injection */
		const duration =
			typeof event.durationSeconds === "number"
				? ` in ${event.durationSeconds.toFixed(1)}s`
				: "";
		const tokens = total > 0 ? ` · ${total} tokens` : "";
		return `[AGY] run done: status=${event.status || "UNKNOWN"}${duration}${tokens}`;
	}

	function formatSessionMetaLine(event) {
		const parts = [];
		if (typeof event.model === "string" && event.model) {
			parts.push(`model=${event.model}`);
		}
		if (typeof event.effort === "string" && event.effort) {
			parts.push(`effort=${event.effort}`);
		}
		if (typeof event.sandbox === "boolean") {
			parts.push(`sandbox=${event.sandbox ? "on" : "off"}`);
		}
		if (typeof event.permissions === "string" && event.permissions) {
			parts.push(`permissions=${event.permissions}`);
		}
		if (typeof event.conversationId === "string" && event.conversationId) {
			parts.push(`conversation=${event.conversationId.slice(0, 8)}`);
		}
		if (parts.length === 0) return null;
		return `[INFO] session: ${parts.join(" ")}`;
	}

	/** Emits one telemetry record for a usage payload (reserved lane budget). */
	function emitUsageRecord(usage, model) {
		const summary = summarizeUsage(usage);
		if (summary === "usage unknown") return null;
		if (telemetryCount >= telemetryMaxCount) return null;
		const entry = appendEntry({
			kind: "telemetry",
			feeds: ["telemetry"],
			text: `[USAGE] ${summary}`,
			meta: { model: typeof model === "string" ? model : null },
			usage: usage && typeof usage === "object" ? { ...usage } : usage,
		});
		telemetryCount += 1;
		return entry;
	}

	/** Emits usage telemetry unless this exact payload was just emitted. */
	function maybeEmitUsage(usage, model) {
		if (!usage || typeof usage !== "object") return null;
		let key;
		try {
			key = JSON.stringify({ usage, model: model ?? null });
		} catch {
			key = null;
		}
		if (key !== null && key === lastUsageJson) return null;
		const entry = emitUsageRecord(usage, model);
		if (entry && key !== null) lastUsageJson = key;
		return entry;
	}

	const handleRunStarted = (event = {}) => {
		turnIndex += 1;
		const flushed = flushOpenBlocks();
		const line = formatRunOpenLine(event);
		if (!line) return flushed;
		const entry = system(line);
		return entry ? [...flushed, entry] : flushed;
	};

	function handleMessageStarted(event) {
		const role = event.message?.role;
		if (role && role !== "assistant") return [];
		messageRole = role || "assistant";
		return flushOpenBlocks();
	}

	function handleAssistantDelta(event) {
		const emitted = [];
		const ame = event.assistantMessageEvent;
		const ameType = ame?.type;
		switch (ameType) {
			case "thinking_start":
				break;
			case "thinking_delta": {
				const delta = typeof ame?.delta === "string" ? ame.delta : "";
				if (delta) thinkingBuffer += delta;
				break;
			}
			case "thinking_end":
				emitted.push(...flushOpenBlocks());
				break;
			case "text_start":
				break;
			case "text_delta": {
				const delta = typeof ame?.delta === "string" ? ame.delta : "";
				if (delta) textBuffer += delta;
				break;
			}
			case "text_end":
				emitted.push(...flushOpenBlocks());
				break;
			case "toolcall_start":
				// Tool args stream inside the message; the actual tool call is
				// logged from the tool_started event. Close any open text block so
				// the narrative stays separate from the call.
				emitted.push(...flushOpenBlocks());
				break;
			case "toolcall_delta":
			case "toolcall_end":
				break;
			case "done":
				emitted.push(...flushOpenBlocks());
				break;
			default: {
				// No protocol tag (or an unknown one): fall back to the bare-delta
				// shapes the engine has always read.
				const delta =
					(typeof event.delta === "string" && event.delta) ||
					(typeof event.chunk === "string" && event.chunk) ||
					(typeof ame?.delta === "string" && ame.delta) ||
					"";
				if (delta) textBuffer += delta;
				break;
			}
		}
		// Usage riding on the delta (pi message usage/stopReason) becomes
		// telemetry instead of dying in the mapper boundary.
		if (event.usage && typeof event.usage === "object") {
			const usageEntry = maybeEmitUsage(event.usage, event.model);
			if (usageEntry) emitted.push(usageEntry);
		}
		return emitted;
	}

	function handleToolStarted(event) {
		const flushed = flushOpenBlocks();
		const toolName = event.toolName || event.name || "tool";
		const toolCallId = event.toolCallId || event.id || null;
		const args = event.args || event.arguments || {};
		const safeArgs = redactDeepStrings(args);
		const entry = appendEntry({
			kind: "tool",
			feeds: ["main", "tools"],
			text: `[TOOL] ${toolName}(${summarizeToolStart(toolName, safeArgs, { maxLength: toolArgsMaxLength })})`,
			meta: { toolName, toolCallId, args: safeArgs, output: "", isError: false },
			tool: { callId: toolCallId, name: toolName, args: safeArgs },
			blockId: `b${nextBlock++}`,
		});
		openToolEntry = entry;
		toolStartMs.set(entry, Date.now());
		return [...flushed, entry];
	}

	function handleToolUpdated(event) {
		const partial = readToolPartial(event);
		if (!partial || !openToolEntry) return [];
		const outputCap = maxEntryBytes > 0 ? maxEntryBytes : 8192;
		const combined = openToolEntry.meta.output
			? `${openToolEntry.meta.output}\n${partial}`
			: partial;
		openToolEntry.meta.output = excerptText(combined, outputCap);
		if (openToolEntry.tool && typeof openToolEntry.tool === "object") {
			openToolEntry.tool = {
				...openToolEntry.tool,
				partials: openToolEntry.meta.output,
			};
		}
		return [];
	}

	function handleToolFinished(event) {
		const toolName =
			event.toolName || event.name || openToolEntry?.meta.toolName || "tool";
		const toolCallId =
			event.toolCallId || event.id || openToolEntry?.meta.toolCallId || null;
		const isError = Boolean(
			event.isError || event.error || event.result?.isError || event.result?.error,
		);
		const resultText = extractToolResultText(event);
		// Per-step timing: explicit harness timings win; otherwise the
		// measured wall-clock between tool_started and tool_finished, but
		// only for steps slow enough to matter (same-tick unit pairs stay
		// byte-identical). Stored on meta/tool always; rendered on [RESULT].
		const startedAt = openToolEntry ? toolStartMs.get(openToolEntry) : null;
		const measuredMs =
			typeof startedAt === "number" ? Date.now() - startedAt : null;
		const durationMs =
			explicitDurationMs(event) ??
			(typeof measuredMs === "number" && measuredMs >= MEASURED_TIMING_FLOOR_MS
				? measuredMs
				: null);
		const timingSuffix =
			typeof durationMs === "number" ? ` (${formatDurationMs(durationMs)})` : "";
		if (openToolEntry) {
			toolStartMs.delete(openToolEntry);
			openToolEntry.meta.isError = isError;
			// Keep the full output record (streamed partials + final result) on
			// the structured tools feed.
			if (resultText) {
				openToolEntry.meta.output = openToolEntry.meta.output
					? `${openToolEntry.meta.output}\n${resultText}`
					: resultText;
			}
			if (openToolEntry.tool && typeof openToolEntry.tool === "object") {
				openToolEntry.tool = {
					...openToolEntry.tool,
					result: resultText,
					partials: openToolEntry.meta.output,
					...(typeof durationMs === "number" ? { durationMs } : {}),
				};
			}
			if (typeof durationMs === "number") {
				openToolEntry.meta.durationMs = durationMs;
			}
		}
		// The [RESULT] excerpt mirrors today's behavior: the tool's FINAL result;
		// streamed partials only stand in when the result itself is empty.
		const fullOutput = resultText || openToolEntry?.meta.output || "";
		openToolEntry = null;

		const emitted = [];
		if (isError) {
			const errDetail = event.error || resultText || "Tool execution error";
			emitted.push(
				appendEntry({
					kind: "error",
					feeds: ["main"],
					text: `[ERROR] Tool ${toolName} failed: ${typeof errDetail === "string" ? errDetail : JSON.stringify(errDetail)}${timingSuffix}`,
					meta: {
						toolName,
						toolCallId,
						...(typeof durationMs === "number" ? { durationMs } : {}),
					},
				}),
			);
			return emitted;
		}
		const excerpt = summarizeToolResult(toolName, fullOutput.trim(), {
			maxLength: resultMaxLength,
		});
		if (excerpt) {
			emitted.push(
				appendEntry({
					kind: "tool",
					feeds: ["tools"],
					text: `[RESULT] ${excerpt}${timingSuffix}`,
					meta: {
						toolName,
						toolCallId,
						...(typeof durationMs === "number" ? { durationMs } : {}),
					},
					tool: {
						callId: toolCallId,
						name: toolName,
						result: resultText,
						...(typeof durationMs === "number" ? { durationMs } : {}),
					},
				}),
			);
		}
		return emitted;
	}

	const handleRunFinished = (event = {}) => {
		const flushed = flushOpenBlocks();
		const emitted = [...flushed];
		if (event.usage && typeof event.usage === "object") {
			const usageEntry = maybeEmitUsage(event.usage, event.model);
			if (usageEntry) emitted.push(usageEntry);
		}
		const line = formatRunDoneLine(event);
		if (!line) return emitted;
		const entry = system(line);
		return entry ? [...emitted, entry] : emitted;
	};

	function handleRunError(event) {
		const flushed = flushOpenBlocks();
		const message =
			event.error?.message ||
			event.message ||
			String(event.error || "Agent error");
		return [
			...flushed,
			appendEntry({
				kind: "error",
				feeds: ["main"],
				text: `[ERROR] ${message}`,
				meta: {},
			}),
		];
	}

	function handleUsageUpdated(event) {
		const entry = maybeEmitUsage(event.usage, event.model);
		return entry ? [entry] : [];
	}

	function handleSessionMeta(event) {
		const line = formatSessionMetaLine(event);
		if (!line) return [];
		return [system(line)];
	}

	function handlePermissionRequested(event) {
		const safeEvent = redactDeepStrings(event || {});
		return [
			appendEntry({
				kind: "permission",
				feeds: ["main"],
				text: summarizePermission(safeEvent),
				meta: {
					method: safeEvent.method ?? null,
					target: safeEvent.target ?? null,
				},
			}),
		];
	}

	function handlePermissionResolved(event) {
		const safeEvent = redactDeepStrings(event || {});
		return [
			appendEntry({
				kind: "permission",
				feeds: ["main"],
				text: summarizePermission(safeEvent),
				meta: {
					method: safeEvent.method ?? null,
					target: safeEvent.target ?? null,
					decision: safeEvent.decision ?? null,
				},
			}),
		];
	}

	function handlePlanUpdated(event) {
		const steps = Array.isArray(event.steps) ? redactDeepStrings(event.steps) : [];
		const safeEvent = redactDeepStrings({ ...event, steps });
		return [
			appendEntry({
				kind: "plan",
				feeds: ["main"],
				text: summarizePlan(safeEvent),
				meta: { steps },
			}),
		];
	}

	function handleReasoningDelta(event) {
		const delta = typeof event.delta === "string" ? event.delta : "";
		if (delta) thinkingBuffer += delta;
		return [];
	}

	function handleHarnessLog(event) {
		const text = typeof event.text === "string" ? event.text : "";
		if (!text.trim()) return [];
		return [system(text)];
	}

	function handleUnknownEvent(event) {
		// Nothing is silently lost: unmapped wire data lands in the bounded
		// raw lane with its source attached (scrubbed + capped) instead of
		// disappearing in a default branch.
		const wireType = typeof event.type === "string" ? event.type : "event";
		const summary = summarizeRaw({
			evidence: { wireType, reason: "unmapped" },
		});
		const entry = appendEntry({
			kind: "raw",
			feeds: ["raw"],
			text: summary,
			meta: {},
			fidelity: FIDELITY_SYNTHESIZED,
			evidence: {
				wireType,
				sourceEvent: boundRawSource(event, rawMaxBytes),
				reason: "unmapped",
			},
		});
		enforceRawBudget();
		return [entry];
	}

	function enforceRawBudget() {
		const rawRecords = entries.filter(
			(e) => e.kind === "raw" && e !== rawEvictionMarker,
		);
		const overflow = rawRecords.length - rawMaxCount;
		if (overflow <= 0) return;
		rawEvictedCount += overflow;
		const victims = new Set(rawRecords.slice(0, overflow));
		for (let i = entries.length - 1; i >= 0; i--) {
			// eslint-disable-next-line security/detect-object-injection -- numeric index into the processor-owned array
			if (victims.has(entries[i])) entries.splice(i, 1);
		}
		const markerText = `[INFO] (${rawEvictedCount} earlier raw entries evicted)`;
		if (!rawEvictionMarker || !entries.includes(rawEvictionMarker)) {
			rawEvictionMarker = makeLogRecord({
				...contextFields,
				id: nextEntryId++,
				seq: nextSeq++,
				ts: new Date().toISOString(),
				feed: "raw",
				feeds: ["raw"],
				kind: "system",
				turn: turnIndex || 1,
				text: markerText,
				meta: { rawEvictedCount },
				fidelity: FIDELITY_SYNTHESIZED,
			});
			entries.push(rawEvictionMarker);
			evictOverflow();
		} else {
			rawEvictionMarker.text = markerText;
			rawEvictionMarker.meta = { rawEvictedCount };
		}
		reconcileLaneCounters();
	}

	function handleEvent(event) {
		if (!event || typeof event.type !== "string") return [];
		switch (event.type) {
			case "run_started":
				return handleRunStarted(event);
			case "message_started":
				return handleMessageStarted(event);
			case "assistant_delta":
				return handleAssistantDelta(event);
			case "tool_started":
				return handleToolStarted(event);
			case "tool_updated":
				return handleToolUpdated(event);
			case "tool_finished":
				return handleToolFinished(event);
			case "run_finished":
				return handleRunFinished(event);
			case "run_error":
				return handleRunError(event);
			case "usage_updated":
				return handleUsageUpdated(event);
			case "session_meta":
				return handleSessionMeta(event);
			case "permission_requested":
				return handlePermissionRequested(event);
			case "permission_resolved":
				return handlePermissionResolved(event);
			case "plan_updated":
				return handlePlanUpdated(event);
			case "reasoning_delta":
				return handleReasoningDelta(event);
			case "harness_log":
				return handleHarnessLog(event);
			default:
				return handleUnknownEvent(event);
		}
	}

	function system(text, kind = "system") {
		if (!text || !String(text).trim()) return null;
		return appendEntry({ kind, feeds: ["main"], text: String(text), meta: {} });
	}

	return {
		handleEvent,
		system,
		get entries() {
			return entries;
		},
	};
}

/**
 * MARK: logRecord
 * @description The canonical log record of the unified log platform: one
 *   additive superset shape for every harness log entry. Legacy entries
 *   (`{ id, ts, feed, feeds, kind, turn, text, meta }`) keep working
 *   untouched; the new optional fields carry everything the old 8-event
 *   pipeline dropped (usage telemetry, permissions, plans, raw evidence,
 *   typed tool payloads).
 *
 *   Pure module: no harness imports and no side effects. Its only imports
 *   are the zero-dependency shared leaf modules (secret redaction, ANSI
 *   stripping), so the record helpers can never drift from the copies the
 *   runner and the UI use. The log processor (`logProcessor.js`) is the
 *   single producer; routes and the UI model upgrade stored entries at
 *   read time via `normalizeRecord` (storage is never rewritten).
 *
 *   ```js
 *   {
 *     // unchanged (every existing reader keeps working)
 *     id, ts, feed, feeds, kind, turn, text, meta,
 *
 *     // ADDITIVE (absent for legacy entries until normalizeRecord runs)
 *     seq,        // monotonic within the stage run
 *     blockId,    // stable id for a semantic block (text/thinking/tool)
 *     runId,      // harness run/conversation id when available
 *     harnessId,  // "pi" | "opencode" | "vibe" | "antigravity" | "muse" | "custom" | "mock"
 *     model,      // resolved model ref
 *     fidelity,   // "exact" | "normalized" | "synthesized"
 *     evidence,   // { wireType, sourceEvent, reason? } — bounded raw lane
 *     tool,       // { callId, name, args, result, exitCode, durationMs, partials }
 *     usage,      // { inputTokens, outputTokens, cachedTokens, totalTokens, costUsd,
 *                 //   contextUsed, contextWindow, steps, tokensPerSecond, model }
 *   }
 *   ```
 *
 *   Kinds: `assistant | thinking | tool | error | system` (original) plus
 *   `telemetry | permission | plan | raw` (unified platform). Feeds:
 *   `main | thinking | tools` (original) plus `telemetry | raw`.
 */

import { redactSecretsText } from "../../../shared/redactSecrets.js";
import { stripAnsi } from "../../../shared/toolLogFormat.js";

/***
 * MARK: RECORD_LIMITS
 * @description Shared caps for the unified log platform. `logEntriesMaxCount`
 *   stays the total bound; the lane budgets below subdivide it so a flood of
 *   raw wire rows can never evict the narrative, and telemetry (tiny records)
 *   keeps a reserved budget.
 ***/
export const RECORD_LIMITS = Object.freeze({
	telemetryMaxCount: 100,
	rawMaxCount: 50,
	rawMaxBytes: 8192,
	maxEntryBytes: 0,
});

/***
 * MARK: KNOWN_RECORD_KINDS
 * @description Every entry kind the unified platform produces.
 ***/
export const KNOWN_RECORD_KINDS = Object.freeze([
	"assistant",
	"thinking",
	"tool",
	"error",
	"system",
	"telemetry",
	"permission",
	"plan",
	"raw",
]);

/***
 * MARK: KNOWN_RECORD_FEEDS
 * @description Every feed the unified platform produces.
 ***/
export const KNOWN_RECORD_FEEDS = Object.freeze([
	"main",
	"thinking",
	"tools",
	"telemetry",
	"raw",
]);

const KNOWN_KINDS = new Set(KNOWN_RECORD_KINDS);
const KNOWN_FEEDS = new Set(KNOWN_RECORD_FEEDS);

/***
 * MARK: FIDELITY_EXACT/NORMALIZED/SYNTHESIZED
 * @description Fidelity semantics for a record's text:
 *   - `exact` — text stored verbatim (assistant/thinking/tool output blocks).
 *   - `normalized` — text reshaped from a structured payload (summaries).
 *   - `synthesized` — engine-authored status/eviction lines.
 ***/
export const FIDELITY_EXACT = "exact";
export const FIDELITY_NORMALIZED = "normalized";
export const FIDELITY_SYNTHESIZED = "synthesized";

/***
 * MARK: stripAnsiText
 * @description Removes terminal color/formatting escape sequences so stored
 *   record text reads clean. Delegates to the shared ANSI stripper (the
 *   same pattern the tool-result summaries use) so the two can never drift;
 *   non-strings become "".
 * @example stripAnsiText('\u001b[32mok\u001b[0m') => 'ok'
 ***/
export function stripAnsiText(text) {
	return stripAnsi(text);
}

/***
 * MARK: scrubSecrets
 * @description Scrubs secret and PII shapes from text bound for the raw
 *   evidence lane. Delegates to the shared content choke point
 *   (`redactSecretsText`) — the only secret-pattern list in the engine —
 *   so the raw lane can never lag behind it. Non-strings become "".
 *   (The log processor re-redacts the bounded string through the same
 *   choke point afterwards, so this scrub is defense in depth for direct
 *   readers of the evidence.)
 * @example scrubSecrets('Bearer abcd1234efgh') => 'Bearer [REDACTED]'
 ***/
export function scrubSecrets(text) {
	return redactSecretsText(text);
}

/***
 * MARK: boundRawSource
 * @description Bounds + scrubs a raw wire payload for the evidence lane:
 *   JSON-encoded (when possible), secrets scrubbed, capped at `rawMaxBytes`
 *   with an ellipsis. Never throws, never returns "" for a real payload.
 * @example boundRawSource({ ok: true }, 100) => '{"ok":true}'
 ***/
export function boundRawSource(sourceEvent, maxBytes = RECORD_LIMITS.rawMaxBytes) {
	let text;
	if (typeof sourceEvent === "string") {
		text = sourceEvent;
	} else {
		try {
			text = JSON.stringify(sourceEvent);
		} catch {
			try {
				text = String(sourceEvent);
			} catch {
				text = "[unserializable wire event]";
			}
		}
	}
	const cap = maxBytes > 0 ? maxBytes : RECORD_LIMITS.rawMaxBytes;
	const scrubbed = scrubSecrets(text);
	if (scrubbed.length <= cap) return scrubbed;
	return `${scrubbed.slice(0, cap)}…`;
}

/***
 * MARK: isKnownFidelity
 * @description Whether a value is one of the three fidelity markers the
 *   platform produces. Anything else (typos, vendor strings) falls back to
 *   the kind-derived default in `makeLogRecord`.
 * @example isKnownFidelity("exact") => true
 ***/
export function isKnownFidelity(value) {
	return (
		value === FIDELITY_EXACT ||
		value === FIDELITY_NORMALIZED ||
		value === FIDELITY_SYNTHESIZED
	);
}

/***
 * MARK: fidelityForKind
 * @description Default fidelity for a legacy entry upgraded by
 *   `normalizeRecord`: verbatim text blocks are exact, summary/system lines
 *   are normalized/synthesized.
 * @example fidelityForKind("assistant") => "exact"
 ***/
export function fidelityForKind(kind) {
	if (kind === "assistant" || kind === "thinking") return FIDELITY_EXACT;
	if (kind === "tool") return FIDELITY_NORMALIZED;
	return FIDELITY_SYNTHESIZED;
}

/***
 * MARK: makeLogRecord
 * @description Builds one canonical record from a partial: fills defaults
 *   (timestamp, empty meta, fidelity by kind), derives `feeds` from `feed`,
 *   and passes every typed field through untouched.
 * @example makeLogRecord({ kind: "assistant", text: "hi" }) => { kind: "assistant", feed: "main", feeds: ["main"], fidelity: "exact", … }
 ***/
export function makeLogRecord(partial = {}) {
	// Fail safe: a null/non-object partial degrades to an empty system
	// record instead of throwing on property access.
	const source =
		partial && typeof partial === "object" && !Array.isArray(partial)
			? partial
			: {};
	const kind =
		typeof source.kind === "string" && KNOWN_KINDS.has(source.kind)
			? source.kind
			: "system";
	const feed =
		typeof source.feed === "string" && KNOWN_FEEDS.has(source.feed)
			? source.feed
			: "main";
	const feeds = Array.isArray(source.feeds)
		? source.feeds.filter((f) => KNOWN_FEEDS.has(f))
		: [feed];
	const turn =
		Number.isFinite(source.turn) && source.turn >= 1
			? Math.floor(source.turn)
			: 1;
	const record = {
		id: source.id ?? null,
		ts:
			typeof source.ts === "string" && source.ts
				? source.ts
				: new Date().toISOString(),
		feed,
		feeds: feeds.length > 0 ? feeds : [feed],
		kind,
		turn,
		text: typeof source.text === "string" ? source.text : "",
		// Arrays are not valid meta bags (downstream readers spread meta);
		// only plain objects pass through.
		meta:
			source.meta && typeof source.meta === "object" && !Array.isArray(source.meta)
				? source.meta
				: {},
		fidelity: isKnownFidelity(source.fidelity)
			? source.fidelity
			: fidelityForKind(kind),
	};
	// Optional typed fields: present only when the producer set them, so
	// legacy readers (and toEqual assertions on legacy shapes) see no noise.
	// Copied explicitly (not via a dynamic-key loop) so a mistyped field
	// name can never leak an undeclared property onto the record.
	if (source.seq !== undefined) record.seq = source.seq;
	if (source.blockId !== undefined) record.blockId = source.blockId;
	if (source.runId !== undefined) record.runId = source.runId;
	if (source.harnessId !== undefined) record.harnessId = source.harnessId;
	if (source.model !== undefined) record.model = source.model;
	if (source.evidence !== undefined) record.evidence = source.evidence;
	if (source.tool !== undefined) record.tool = source.tool;
	if (source.usage !== undefined) record.usage = source.usage;
	return record;
}

/***
 * MARK: normalizeRecord
 * @description Upgrades a legacy/streamer entry to the canonical shape at
 *   read time: missing `feeds` derive from `feed`, missing `fidelity`
 *   derives from `kind`, missing `meta` becomes {}. Already-canonical
 *   records pass through with their typed fields intact. Storage is never
 *   rewritten — callers use the returned record for rendering.
 * @example normalizeRecord({ kind: "assistant", feed: "main", text: "hi" }) => { feeds: ["main"], fidelity: "exact", … }
 ***/
export function normalizeRecord(entry) {
	if (!entry || typeof entry !== "object") {
		return makeLogRecord({ kind: "system", text: "" });
	}
	return makeLogRecord({
		...entry,
		feeds: Array.isArray(entry.feeds) ? entry.feeds : undefined,
		feed: entry.feed,
	});
}

